#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Write engine/sc_tables.h: the constant tables the engine reads instead of calling pow / tan / sin
(the FM-1 has no FPU). Every table is for 44.1 kHz, the FM-1's rate."""
import math
from pathlib import Path

FS = 44100
out = ["/* SPDX-License-Identifier: GPL-3.0-only */",
       "/* Generated by tools/gen_tables.py - do not edit. Tables for FS = 44100 Hz. */",
       "#ifndef SC_TABLES_H", "#define SC_TABLES_H", "#include <stdint.h>", ""]

def hz(note):
    return 440.0 * 2.0 ** ((note - 69.0) / 12.0)

# Phase increment (2^32 = one cycle per sample) for notes 132..144 in 1/64-semitone steps; lower
# octaves shift it right. 769 entries so the last step can interpolate.
pitch = [round(2**32 * hz(132 + i / 64) / FS) for i in range(769)]
assert max(pitch) < 2**32
out.append("/* sc_pitch_inc(): phase increment of notes 132 + i/64 */")
out.append("static const uint32_t SC_PITCH_T[769] = {")
out += ["    " + ", ".join(f"{v}u" for v in pitch[i:i + 8]) + "," for i in range(0, len(pitch), 8)]
out.append("};\n")

# The filter's g = tan(pi fc / FS) in Q28 for cutoff notes 0..132 in 1/8-semitone steps, fc clamped
# to [20 Hz, 0.45 FS] as svfCoeffs() does. 1058 entries (one past 132 to interpolate).
g = []
for i in range(1058):
    fc = min(max(hz(i / 8), 20.0), FS * 0.45)
    g.append(round(math.tan(math.pi * fc / FS) * 2**28))
assert max(g) < 2**31
out.append("/* cutoff note i/8 -> g = tan(pi fc / FS), Q28 */")
out.append("static const uint32_t SC_CUT_G[1058] = {")
out += ["    " + ", ".join(f"{v}u" for v in g[i:i + 8]) + "," for i in range(0, len(g), 8)]
out.append("};\n")

# One sine cycle, Q15, 1025 entries (the last repeats the first for interpolation).
sine = [round(math.sin(2 * math.pi * i / 1024) * 32767) for i in range(1025)]
out.append("/* sin(2 pi i / 1024), Q15 */")
out.append("static const int16_t SC_SINE[1025] = {")
out += ["    " + ", ".join(str(v) for v in sine[i:i + 12]) + "," for i in range(0, len(sine), 12)]
out.append("};\n")

# log2(1 + i/64) and 2^(i/64), Q16, for the limiter's gain computer (65 entries: interpolation)
lg = [round(math.log2(1 + i / 64) * 65536) for i in range(65)]
ex = [round(2 ** (i / 64) * 65536) for i in range(65)]
out.append("/* log2(1 + i/64), Q16 */")
out.append("static const uint32_t SC_LOG2_T[65] = {")
out += ["    " + ", ".join(f"{v}u" for v in lg[i:i + 10]) + "," for i in range(0, len(lg), 10)]
out.append("};\n")
out.append("/* 2^(i/64), Q16 */")
out.append("static const uint32_t SC_EXP2_T[65] = {")
out += ["    " + ", ".join(f"{v}u" for v in ex[i:i + 10]) + "," for i in range(0, len(ex), 10)]
out.append("};\n")

out.append("#endif")
Path(__file__).resolve().parent.parent.joinpath("engine/sc_tables.h").write_text("\n".join(out) + "\n")
print("engine/sc_tables.h:", len(pitch), "pitch,", len(g), "cutoff,", len(sine), "sine")
